var auditColumns = []string{"event_id", "timestamp", "user_id", "user_name", "source_ip", "session_id", "event_type", "target_type", "target_id", "before_value", "after_value", "request_id", "result", "previous_hash", "event_hash"}

// The CSV carries the Korean label as well, because the spreadsheet is read
// outside the console where no lookup is available.
var auditCSVColumns = append([]string{"event_label"}, auditColumns...)

func (s *Server) listAudit(w http.ResponseWriter, r *http.Request) {
	// The screen used to show the newest rows matching the filter and stop
	// there, with nothing saying more existed: an investigation that reached
	// the bottom of the page had no way to go further back except by guessing
	// at date filters. One row past the page tells the reader there is more
	// without counting a table that only grows.
	limit, offset := parsePage(r)
	query := r.URL.Query()
	where := "TRUE"
	args := []any{}
	// event_type is matched as a prefix so that typing "LOGIN" also finds
	// LOGIN_FAIL and LOGIN_LOCKED, which is what the filter box implies.
	if event := strings.TrimSpace(query.Get("event")); event != "" {
		args = append(args, event+"%")
		where += ` AND event_type ILIKE $` + intString(len(args))
	}
	if user := strings.TrimSpace(query.Get("user")); user != "" {
		args = append(args, "%"+user+"%")
		where += ` AND (user_name ILIKE $` + intString(len(args)) + ` OR source_ip ILIKE $` + intString(len(args)) + `)`
	}
	// "What happened to this Control?" was a question the log could answer and
	// the screen could not ask: the target is shown on every row but there was
	// no way to filter by it. Exact match, which is what the target index on
	// audit_logs is for.
	if target := strings.TrimSpace(query.Get("target")); target != "" {
		args = append(args, target)
		where += ` AND target_id=$` + intString(len(args))
	}
	if targetType := strings.TrimSpace(query.Get("target_type")); targetType != "" {
		args = append(args, strings.ToUpper(targetType))
		where += ` AND target_type=$` + intString(len(args))
	}
	// A chain-break alert names the event the verification stopped at, and an
	// administrator following that alert needs to land on that one event
	// rather than on a page of two hundred.
	if eventID := strings.TrimSpace(query.Get("event_id")); eventID != "" {
		args = append(args, eventID)
		where += ` AND event_id=$` + intString(len(args))
	}
	// "Show me what was refused" is the question an auditor opens this screen
	// with, and the column was there to read but not to filter by.
	if result := strings.ToUpper(strings.TrimSpace(query.Get("result"))); result != "" {
		args = append(args, result)
		where += ` AND result=$` + intString(len(args))
	}
	if from := strings.TrimSpace(query.Get("from")); from != "" {
		args = append(args, from)
		where += ` AND timestamp >= display_day_start($` + intString(len(args)) + `::date)`
	}
	if to := strings.TrimSpace(query.Get("to")); to != "" {
		args = append(args, to)
		where += ` AND timestamp < display_day_start($` + intString(len(args)) + `::date + 1)`
	}
	// One row past the cap tells us the export was cut short without a second
	// count query over a table that is only ever appended to.
	if query.Get("format") == "csv" {
		limit, offset = exportRowCap+1, 0
	}
	args = append(args, limit+1, offset)
	rows, err := s.Store.Pool.Query(r.Context(), `SELECT event_id,timestamp,user_id,user_name,source_ip,session_id,event_type,target_type,target_id,before_value,after_value,request_id,result,previous_hash,event_hash FROM audit_logs WHERE `+where+` ORDER BY timestamp DESC,chain_sequence DESC LIMIT $`+intString(len(args)-1)+` OFFSET $`+intString(len(args)), args...)
	if err != nil {
		s.fault(w, r, "QUERY_FAILED", "감사 로그를 불러오지 못했습니다.", err)
		return
	}
	records, err := scanDynamic(rows, auditColumns)
	if err != nil {
		s.fault(w, r, "QUERY_FAILED", "감사 로그를 불러오지 못했습니다.", err)
		return
	}
	for _, record := range records {
		if code, ok := record["event_type"].(string); ok {
			record["event_label"] = auditEventLabels[code]
		}
	}
	hasMore := len(records) > limit
	if hasMore {
		records = records[:limit]
	}
	if query.Get("format") == "csv" {
		records, truncated := capExport(w, records)
		_ = s.Store.Audit(r.Context(), auditFrom(r, "EXPORT_AUDIT", "AUDIT_LOG", "", nil, map[string]any{"rows": len(records), "truncated": truncated}))
		writeCSV(w, "seccheck-audit", s.Store.Location(r.Context()), auditCSVColumns, records)
		return
	}
	jsonResponse(w, 200, map[string]any{"items": records, "events": auditEventCatalogue(), "has_more": hasMore, "limit": limit, "offset": offset})
}

// exportRowCap bounds a single export so that one download cannot pull an
// installation's entire history into memory. Hitting it is reported rather
// than hidden: a compliance export that quietly stops at fifty thousand rows
package mail

import (
	"context"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Delivery is one attempt to hand a message to the relay: when, for which
// event, to whom, with what subject, and whether the relay took it. The body
// is deliberately not kept -- the record answers "did it go out", and a
// record that also held every body would be a second copy of everything
// the service ever said.
type Delivery struct {
	ID             string    `json:"id"`
	CreatedAt      time.Time `json:"created_at"`
	Event          string    `json:"event"`
	RecipientID    string    `json:"recipient_id"`
	Recipient      string    `json:"recipient"`
	Subject        string    `json:"subject"`
	Status         string    `json:"status"`
	Attempt        int       `json:"attempt"`
	Error          string    `json:"error"`
	NotificationID string    `json:"notification_id"`
}

// Delivery statuses. SENT and FAILED are the relay's answer; SKIPPED is the
// service deciding not to try, with the reason in Error, so that "it never
// came" can still be answered from the record.
const (
	StatusSent    = "SENT"
	StatusFailed  = "FAILED"
	StatusSkipped = "SKIPPED"
)

// Events the service itself originates, outside the notification catalogue.
const (
	EventTest   = "TEST"
	EventDigest = "DIGEST"
)

// Record keeps one attempt. The caller has already done or decided the
// sending; a failure to write the record is returned so the caller can log
// it, but it never becomes the failure of the send.
func Record(ctx context.Context, pool *pgxpool.Pool, id string, d Delivery) error {
	if d.Status == "" {
		d.Status = StatusSent
	}
	if d.Attempt < 1 {
		d.Attempt = 1
	}
	_, err := pool.Exec(ctx, `INSERT INTO mail_deliveries(id,event_type,recipient_id,recipient,subject,status,attempt,error,notification_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, d.Event, d.RecipientID, d.Recipient, truncate(d.Subject, 500), d.Status, d.Attempt, truncate(d.Error, 1000), d.NotificationID)
	return err
}

// Outcome turns a send result into a status and message for the record.
func Outcome(err error) (status, message string) {
	if err == nil {
		return StatusSent, ""
	}
	return StatusFailed, err.Error()
}

// Page is what the administrator's record screen shows: the newest attempts
// and how many of each outcome exist in total.
type Page struct {
	Items   []Delivery       `json:"items"`
	Summary map[string]int64 `json:"summary"`
}

// List returns the newest attempts, optionally only those with one status,
// newest first, and the count of every status regardless of the filter.
func List(ctx context.Context, pool *pgxpool.Pool, status string, limit, offset int) (Page, error) {
	page := Page{Items: []Delivery{}, Summary: map[string]int64{StatusSent: 0, StatusFailed: 0, StatusSkipped: 0}}
	status = strings.ToUpper(strings.TrimSpace(status))
	rows, err := pool.Query(ctx, `SELECT id,created_at,event_type,recipient_id,recipient,subject,status,attempt,error,notification_id FROM mail_deliveries
                WHERE ($1='' OR status=$1) ORDER BY created_at DESC LIMIT $2 OFFSET $3`, status, limit, offset)
	if err != nil {
		return page, err
	}
	defer rows.Close()
	for rows.Next() {
		var d Delivery
		if err := rows.Scan(&d.ID, &d.CreatedAt, &d.Event, &d.RecipientID, &d.Recipient, &d.Subject, &d.Status, &d.Attempt, &d.Error, &d.NotificationID); err != nil {
			return page, err
		}
		page.Items = append(page.Items, d)
	}
	if err := rows.Err(); err != nil {
		return page, err
	}
	counts, err := pool.Query(ctx, `SELECT status,count(*) FROM mail_deliveries GROUP BY status`)
	if err != nil {
		return page, err
	}
	defer counts.Close()
	for counts.Next() {
		var s string
		var n int64
		if err := counts.Scan(&s, &n); err != nil {
			return page, err
		}
		page.Summary[s] = n
	}
	return page, counts.Err()
}

func truncate(v string, n int) string {
	if len(v) <= n {
		return v
	}
	return v[:n]
}
// Package testdb gives tests a real PostgreSQL schema so that migrations,
// object-level authorization, workflow transitions and submission validation
// are exercised against the database they actually run on. Without
// TEST_POSTGRES_DSN the helpers skip, so `go test ./...` still works on a
// machine with no database.
package testdb

import (
	"context"
	"fmt"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/hkjang/SecCheck/internal/store"
)

const DSNEnv = "TEST_POSTGRES_DSN"

var counter atomic.Int64

// DSN returns the configured test database, or "" when the suite should skip.
func DSN() string { return strings.TrimSpace(os.Getenv(DSNEnv)) }

// New creates an isolated schema, applies every migration to it and returns a
// Store bound to that schema. The schema is dropped when the test finishes, so
// parallel packages never see each other's rows.
func New(t *testing.T) *store.Store {
	t.Helper()
	return open(t, true)
}

func open(t *testing.T, migrate bool) *store.Store {
	t.Helper()
	dsn := DSN()
	if dsn == "" {
		t.Skipf("%s is not set; skipping the database-backed test", DSNEnv)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()

	admin, err := store.Open(ctx, dsn)
	if err != nil {
		t.Fatalf("connect %s: %v", DSNEnv, err)
	}
	schema := fmt.Sprintf("t%d_%d", time.Now().UnixNano()%1e9, counter.Add(1))
	if _, err = admin.Pool.Exec(ctx, `CREATE SCHEMA `+schema); err != nil {
		admin.Close()
		t.Fatalf("create schema %s: %v", schema, err)
	}

	scoped, err := store.Open(ctx, store.WithSearchPath(dsn, schema))
	if err != nil {
		_, _ = admin.Pool.Exec(ctx, `DROP SCHEMA `+schema+` CASCADE`)
		admin.Close()
		t.Fatalf("connect to schema %s: %v", schema, err)
	}
	if err = migrateIf(migrate, ctx, scoped); err != nil {
		scoped.Close()
		_, _ = admin.Pool.Exec(ctx, `DROP SCHEMA `+schema+` CASCADE`)
		admin.Close()
		t.Fatalf("migrate schema %s: %v", schema, err)
	}
	t.Cleanup(func() {
		scoped.Close()
		dropCtx, stop := context.WithTimeout(context.Background(), 30*time.Second)
		defer stop()
		if _, err := admin.Pool.Exec(dropCtx, `DROP SCHEMA `+schema+` CASCADE`); err != nil {
			t.Logf("drop schema %s: %v", schema, err)
		}
		admin.Close()
	})
	return scoped
}

// Bootstrap creates the initial administrator the way main does, and returns
// the user id.
func Bootstrap(t *testing.T, s *store.Store, username string) string {
	t.Helper()
	ctx := context.Background()
	if err := s.UpsertBootstrap(ctx, store.NewID(), username, "$2a$04$C4a8yXqTRIYQGvPMqmzZ2eOWiHZs4v4CjJZaFn8DR5JzS0/oCJhwq"); err != nil {
		t.Fatalf("bootstrap %s: %v", username, err)
	}
	u, err := s.GetUserByUsername(ctx, username)
	if err != nil {
		t.Fatalf("load %s: %v", username, err)
	}
	return u.ID
}

func migrateIf(migrate bool, ctx context.Context, s *store.Store) error {
	if !migrate {
		return nil
	}
	return s.Migrate(ctx)
}

// Bare creates an isolated empty schema and returns a Store bound to it with
// no migrations applied, for tests that need to build a database up from some
// earlier state themselves.
func Bare(t *testing.T) *store.Store {
	t.Helper()
	return open(t, false)
}
