name: offline-image-release

on:
  push:
    tags: ['v*.*.*']
  # Re-cutting the offline image for a tag that already exists -- a runner
  # that died mid-build, a registry that was unreachable -- otherwise means
  # deleting and re-pushing the tag.
  workflow_dispatch:
    inputs:
      tag:
        description: '다시 빌드할 태그 (예: v1.0.124)'
        required: true

permissions:
  contents: write
  id-token: write
  attestations: write

jobs:
  release:
    runs-on: ubuntu-latest
    # The release gate has to run the same database-backed tests as CI.
    # Without PostgreSQL the integration suite skips silently, so a tag could
    # be cut from a commit whose CI run was red — which is exactly what
    # happened with v0.20.0.
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_PASSWORD: seccheck_ci
          POSTGRES_DB: seccheck
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U postgres -d seccheck"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 20
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ inputs.tag || github.ref }}
      - uses: actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e # v7.0.0
        with:
          go-version-file: go.mod
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: 22
      - name: Validate release version
        id: version
        shell: bash
        run: |
          ref="${{ inputs.tag || github.ref_name }}"
          version="${ref#v}"
          test "$(tr -d '\r\n' < VERSION)" = "$version"
          echo "version=$version" >> "$GITHUB_OUTPUT"
          echo "tag=$ref" >> "$GITHUB_OUTPUT"
          # The commit under test is the one checked out, which for a manual
          # re-cut is the tag rather than whatever the branch points at now.
          echo "sha=$(git rev-parse HEAD)" >> "$GITHUB_OUTPUT"
      - name: Require a green security-ci run for this commit
        env:
          GH_TOKEN: ${{ github.token }}
        shell: bash
        run: |
          # Running the tests again here is not enough on its own: the tag is a
          # separate event from the push, and the release job does not repeat
          # the vulnerability, secret, container and DAST gates. Refusing to
          # publish a commit whose CI is not green covers all of them.
          for attempt in $(seq 1 60); do
            status=$(gh run list --workflow=ci.yml --commit "${{ steps.version.outputs.sha }}" \
              --repo "$GITHUB_REPOSITORY" --limit 1 --json status,conclusion \
              --jq '.[0] | "\(.status) \(.conclusion)"' || echo "")
            case "$status" in
              "completed success")
                echo "security-ci passed for ${{ steps.version.outputs.sha }}"
                exit 0 ;;
              "completed "*)
                echo "::error::security-ci concluded '${status#completed }' for ${{ steps.version.outputs.sha }}; refusing to release"
                exit 1 ;;
              "")
                echo "no security-ci run found for ${{ steps.version.outputs.sha }} yet (attempt $attempt)" ;;
              *)
                echo "security-ci is $status (attempt $attempt)" ;;
